import { useRef, useState, type FormEvent } from 'react';
import { JxAlert, JxButton, JxInputField, JxSelect, JxSwitch } from '@jinx-ui/react';

const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;

const ROLE_OPTIONS = [
  { value: 'viewer', label: 'Наблюдатель', meta: 'только чтение' },
  { value: 'editor', label: 'Редактор', meta: 'правит контент' },
  { value: 'admin', label: 'Администратор', meta: 'полный доступ' },
];

export default function TeamInviteForm() {
  const [email, setEmail] = useState('');
  const [touched, setTouched] = useState(false);
  const [role, setRole] = useState('editor');
  const [notify, setNotify] = useState(true);
  const [invitedEmail, setInvitedEmail] = useState<string | null>(null);

  const emailInputRef = useRef<HTMLInputElement>(null);
  const closeAlertRef = useRef<HTMLButtonElement>(null);

  const trimmedEmail = email.trim();
  const isEmailValid = EMAIL_PATTERN.test(trimmedEmail);
  const errorText =
    touched && !isEmailValid
      ? trimmedEmail.length === 0
        ? 'Укажите почту: без неё приглашение не отправить'
        : 'Адрес не похож на почту — пример: name@company.com'
      : undefined;

  const submit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    setTouched(true);
    if (!isEmailValid) {
      emailInputRef.current?.focus();
      return;
    }
    setInvitedEmail(trimmedEmail);
    setEmail('');
    setTouched(false);
    window.requestAnimationFrame(() => closeAlertRef.current?.focus());
  };

  const dismissAlert = () => {
    setInvitedEmail(null);
    emailInputRef.current?.focus();
  };

  return (
    <div style={{ display: 'grid', gap: '16px', maxWidth: '420px' }}>
      {invitedEmail !== null && (
        <div
          role="status"
          onKeyDown={(event) => {
            if (event.key === 'Escape') dismissAlert();
          }}
          style={{ display: 'flex', alignItems: 'flex-start', gap: '8px' }}
        >
          <JxAlert intent="success" title="Приглашение отправлено" style={{ flex: '1 1 auto', minWidth: 0 }}>
            <span style={{ overflowWrap: 'anywhere' }}>
              {invitedEmail} получит письмо со ссылкой. Ссылка живёт 7 дней.
            </span>
          </JxAlert>
          <JxButton
            ref={closeAlertRef}
            iconOnly
            variant="ghost"
            size="sm"
            aria-label="Закрыть сообщение об отправке"
            onClick={dismissAlert}
          >
            ✕
          </JxButton>
        </div>
      )}

      <form onSubmit={submit} noValidate style={{ display: 'grid', gap: '16px' }}>
        <JxInputField
          ref={emailInputRef}
          label="Электронная почта"
          type="email"
          name="email"
          required
          autoComplete="email"
          placeholder="name@company.com"
          value={email}
          onChange={(event) => setEmail(event.target.value)}
          onBlur={() => setTouched(true)}
          helperText="Приглашение придёт на этот адрес. Позвать сразу нескольких можно по одному человеку за раз."
          errorText={errorText}
        />

        <JxSelect
          label="Роль в команде"
          options={ROLE_OPTIONS}
          value={role}
          onValueChange={setRole}
          placeholder="Выберите роль"
        />

        <JxSwitch
          label="Отправить уведомление"
          name="notify"
          checked={notify}
          onChange={(event) => setNotify(event.target.checked)}
        />

        <div style={{ display: 'flex', justifyContent: 'flex-end' }}>
          <JxButton type="submit" variant="primary" disabled={!isEmailValid}>
            Отправить приглашение
          </JxButton>
        </div>
      </form>
    </div>
  );
}

